import sys, json, random, base64, struct, subprocess
sys.path.insert(0, '/workspace/tmp')
from kt import ktest, u, CLI

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 7)

NAMES = ["a", "b", "c", "d", "e", "f", "g", "h"]

def rand_type(depth=0):
    kinds = ["bool", "char", "int", "string", "enum"]
    if depth < 2:
        kinds += ["array", "struct", "alias"]
    kind = random.choice(kinds)
    if kind == "int":
        return {"name": random.choice(NAMES) + "I", "kind": "int",
                "bits": random.choice([1, 8, 9, 16, 32, 64])}
    if kind == "string":
        return {"name": random.choice(NAMES) + "S", "kind": "string",
                "maxsize": random.choice([0, 1, 3, 8])}
    if kind == "enum":
        return {"name": random.choice(NAMES) + "E", "kind": "enum",
                "values": ["v%d" % i for i in range(random.randint(1, 4))]}
    return {"name": random.choice(NAMES) + kind, "kind": kind}

def rand_expr(vars, depth=0):
    if depth > 3 or not vars or random.random() < 0.3:
        return ["var", random.choice(vars)]
    op = random.choice(["eq", "ne", "lt", "le", "gt", "ge", "add", "sub",
                        "and", "or", "implies"])
    return [op, rand_expr(vars, depth + 1), rand_expr(vars, depth + 1)]

def build():
    types = []
    for _ in range(random.randint(0, 5)):
        t = rand_type()
        if t["kind"] == "array":
            t["element"] = random.choice([x["name"] for x in types]) if types else "Bool"
            t["size"] = random.randint(0, 3)
        elif t["kind"] == "struct":
            t["fields"] = [["f%d" % i, random.choice([x["name"] for x in types] or ["Bool"])]
                           for i in range(random.randint(0, 2))]
        elif t["kind"] == "alias":
            t["target"] = random.choice([x["name"] for x in types] or ["Bool"])
        types.append(t)
    types.append({"name": "Bool", "kind": "bool"})
    names = [t["name"] for t in types]
    modules = []
    for i in range(random.randint(1, 4)):
        params = [["p%d" % j, random.choice(names)] for j in range(random.randint(0, 3))]
        result = ["r", random.choice(names)]
        modules.append({"name": "m%d" % i, "params": params, "result": result,
                        "requires": random.choice([None, rand_expr([p[0] for p in params])])})
    mnames = [m["name"] for m in modules]
    calls = []
    for _ in range(random.randint(0, 3)):
        a, b = random.choice(mnames), random.choice(mnames)
        if a != b:
            calls.append([a, b])
    pipes = []
    for _ in range(random.randint(0, 2)):
        target, filt = random.choice(mnames), random.choice(mnames)
        if target == filt:
            continue
        fparams = dict(modules[mnames.index(filt)]["params"])
        tparams = dict(modules[mnames.index(target)]["params"])
        shared = [p for p in fparams if p in tparams]
        if not shared:
            continue
        bind = {p: p for p in shared}
        pipes.append({"target": target, "filter": filt, "bind": bind})
    entries = random.sample(mnames, random.randint(1, len(mnames)))
    runs = []
    for _ in range(random.randint(0, 6)):
        entry = random.choice(entries)
        objects = []
        for i in range(random.randint(0, 8)):
            objects.append(("x%d" % i, bytes([random.randint(0, 255) for _ in range(random.randint(0, 4))])))
        runs.append({"entry": entry, "ktest": ktest(objects)})
    return {"types": types, "modules": modules, "calls": calls, "pipes": pipes,
            "entries": entries, "machine": None, "runs": runs}

bad = 0
for iteration in range(300):
    camp = build()
    payload = json.dumps(camp).encode()
    proc = subprocess.run([sys.executable, "-I", "-B", CLI], input=payload, capture_output=True)
    if proc.returncode != 0:
        bad += 1
        print("CRASH on iteration", iteration, proc.stderr.decode()[:1500])
        print(json.dumps(camp)[:2000])
        break
    try:
        out = json.loads(proc.stdout.decode())
    except Exception as exc:
        bad += 1
        print("BAD JSON", exc, proc.stdout[:400])
        break
    if set(out) != {"plans", "records", "corpus"}:
        bad += 1
        print("BAD KEYS", set(out))
        break
    for plan in out["plans"]:
        if set(plan) != {"entry", "modules", "types", "slots", "flag", "variables"}:
            bad += 1; print("BAD PLAN KEYS", set(plan)); break
    for record in out["records"]:
        if record["status"] in ("READY", "DUPLICATE"):
            if set(record) != {"status", "case", "model_result"}:
                bad += 1; print("BAD RECORD", record); break
        elif set(record) != {"status"}:
            bad += 1; print("BAD RECORD", record); break
    for case in out["corpus"]:
        if set(case) != {"entry", "inputs", "cost", "commands", "witnesses"}:
            bad += 1; print("BAD CASE", case); break
print("fuzz done, failures:", bad)
PYEOF
cd /workspace && python3 tmp/fuzz.py 7
